import java.util.Scanner;

public class Main {
    static long[] ones = new long[17];

    static int computeCost(long n, int i) {
        int totalCost = i * (int)(n / ones[i]);
        n %= ones[i];
        if (n == 0) return totalCost;
        int costOption1 = i + computeCost(ones[i] - n, i - 1);
        int costOption2 = computeCost(n, i - 1);
        return totalCost + Math.min(costOption1, costOption2);
    }

    public static void main(String[] args) {
        Scanner scanner = new Scanner(System.in);
        ones[0] = 0;
        for (int j = 1; j < 17; ++j) {
            ones[j] = ones[j - 1] * 10 + 1;
        }
        long number_input = scanner.nextLong();
        System.out.println(computeCost(number_input, 16));
        scanner.close();
    }
}
